def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest strictly increasing subsequence ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest strictly decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = max(inc[i] + dec[i] - 1 for i in range(n))

    # Minimum removals to achieve a bitonic (choir) formation
    return n - max_bitonic
